// ---- client-src/20-api.js ----
/**
 * Wire helpers: the authenticated unary RPC route, the byte/stream routes, and
 * the address helpers the reader uses for covers and inline images.
 *
 * URL forms are document-relative on purpose: the page may be mounted under a
 * prefix, and Connection's routes resolve against the document base.
 */

/** Build one coded error the views can branch on. */
function readingError(code, message) {
  const error = new Error(message)
  error.code = code
  return error
}

/** Resolve the plugin's own HTTP surface. */
function createReadingApi(ctx) {
  const documentBase = () => document.baseURI || `${location.origin}/`
  const absolute = (path) => new URL(path, documentBase()).href

  /**
   * Call one unary RPC endpoint and unwrap its result.
   *
   * This is a plain same-origin POST to the plugin's authenticated
   * `/api/reading/rpc` route: the browser cookie is sent automatically, and we
   * do not depend on Connection's dedicated per-channel RPC registry.
   */
  async function rpc(endpoint, payload, signal) {
    const url = absolute('api/reading/rpc')
    let response
    try {
      response = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ endpoint, payload: payload ?? {} }),
        signal,
      })
    } catch (error) {
      if (error && error.name === 'AbortError') throw error
      throw readingError('reading/transport-failed', error instanceof Error ? error.message : String(error))
    }
    const result = await response.json().catch(() => null)
    if (!result || result.ok !== true) {
      const failure = result && result.error ? result.error : {}
      throw readingError(failure.code || 'reading/rpc-failed', failure.message || tr('请求失败。', 'Request failed.'))
    }
    return result.value
  }

  const coverUrl = (bookId) => absolute(`api/reading/cover?id=${encodeURIComponent(bookId)}`)
  const assetUrl = (bookId, name) =>
    absolute(`api/reading/asset?book=${encodeURIComponent(bookId)}&name=${encodeURIComponent(name)}`)

  /** Upload one EPUB file's bytes and import it on the Host. */
  async function uploadEpub(file, signal) {
    const url = absolute(`api/reading/import?name=${encodeURIComponent(file.name || 'book.epub')}`)
    let response
    try {
      response = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/octet-stream' },
        body: file,
        signal,
      })
    } catch (error) {
      if (error && error.name === 'AbortError') throw error
      throw readingError('reading/upload-failed', tr('上传失败：', 'Upload failed: ') + (error instanceof Error ? error.message : String(error)))
    }
    const data = await response.json().catch(() => null)
    if (!response.ok || !data || data.ok !== true) {
      const failure = data && data.error ? data.error : {}
      throw readingError(failure.code || 'reading/import-failed', failure.message || `HTTP ${response.status}`)
    }
    return data
  }

  /** Stream one model answer as server-sent events. */
  async function streamAsk(payload, options = {}) {
    const { signal, onDelta, onReasoning, onModel, onUsage, onError, onDone } = options
    const url = absolute('api/reading/ask')
    let response
    try {
      response = await fetch(url, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(payload),
        signal,
      })
    } catch (error) {
      if (error && error.name === 'AbortError') return
      throw readingError('reading/ask-failed', error instanceof Error ? error.message : String(error))
    }
    if (!response.ok || !response.body) {
      throw readingError('reading/ask-failed', `HTTP ${response.status}`)
    }
    const reader = response.body.getReader()
    const decoder = new TextDecoder()
    let buffer = ''
    let settled = false
    const handleFrame = (frame) => {
      const line = frame.split('\n').find((entry) => entry.startsWith('data:'))
      if (!line) return
      let data
      try {
        data = JSON.parse(line.slice(5).trim())
      } catch {
        return
      }
      if (typeof data.delta === 'string') onDelta?.(data.delta)
      else if (typeof data.reasoning === 'string') onReasoning?.(data.reasoning)
      else if (data.model && typeof data.model === 'object') onModel?.(data.model)
      else if (data.usage && typeof data.usage === 'object') onUsage?.(data.usage)
      else if (data.error) {
        settled = true
        onError?.(readingError(data.error.code || 'reading/ask-failed', data.error.message || '回答失败'))
      } else if (data.done === true) {
        settled = true
        onDone?.()
      }
    }
    try {
      for (;;) {
        const { value, done } = await reader.read()
        if (done) break
        buffer += decoder.decode(value, { stream: true })
        let index
        while ((index = buffer.indexOf('\n\n')) >= 0) {
          handleFrame(buffer.slice(0, index))
          buffer = buffer.slice(index + 2)
        }
      }
      if (!settled) onDone?.()
    } catch (error) {
      if (error && error.name === 'AbortError') return
      throw error
    } finally {
      try {
        reader.releaseLock()
      } catch {
        // The stream may already be closed.
      }
    }
  }

  return { rpc, coverUrl, assetUrl, uploadEpub, streamAsk }
}

// ---- client-src/30-store.js ----
/**
 * Reading page state.
 *
 * One external store owns the shelf, the open book, the selection/ask session and
 * the notes list; every view subscribes through `useReading()` and mutates through
 * `readingActions`. Host calls live here, so views stay presentational.
 */

/** The one live store; assigned by `createReadingStore`. */
let READING_STORE = null
/** The one live action set; assigned by `createReadingStore`. */
let READING_ACTIONS = null
/** The one live wire helper set; assigned by `createReadingStore`. */
let READING_API = null

const INITIAL_STATE = {
  status: 'loading',
  error: null,
  view: 'shelf',
  shelf: { books: [], settings: {}, notesCount: 0, libraryDir: '' },
  importing: false,
  current: null,
  loadingBook: false,
  reading: { tocOpen: false, notesOpen: false, settingsOpen: false },
  progress: { chapterIndex: 0, scrollRatio: 0, percent: 0 },
  selection: null,
  ask: {
    // Persistent reader conversation: one message list, streamed answer into the
    // trailing assistant message. The right-hand chat pane is always visible.
    messages: [],
    // A selection parked for "自己提问": the composer sends it with the next text.
    draftQuote: null,
    streaming: false,
    // Model picker state: directory cache and the chosen route (null = default).
    models: null,
    modelsLoading: false,
    modelsError: null,
    selection: null,
    activeModel: null,
  },
  notes: [],
  notesLoading: false,
  search: { open: false, q: '', loading: false, results: [] },
  toast: null,
}

/** Subscribe one component to the reading store. */
function useReading() {
  if (!READING_STORE) throw new Error('reading store is not initialised')
  return useStore(READING_STORE)
}

/** Download a text file the browser owns (notes export). */
function downloadText(fileName, text, mediaType = 'text/markdown;charset=utf-8') {
  const blob = new Blob([text], { type: mediaType })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = fileName
  anchor.style.display = 'none'
  document.body.appendChild(anchor)
  anchor.click()
  anchor.remove()
  setTimeout(() => URL.revokeObjectURL(url), 2000)
}

/** Create the store, actions and wire helpers for one Client plugin instance. */
function createReadingStore(ctx) {
  const store = createStore({ ...INITIAL_STATE, shelf: { ...INITIAL_STATE.shelf }, reading: { ...INITIAL_STATE.reading } })
  const api = createReadingApi(ctx)
  const set = store.set
  const get = store.get
  let bootstrapped = false
  let askAbort = null
  let pendingImportAbort = null

  // The model choice survives a page refresh: it is optional UI state, so a plain
  // localStorage slot is enough and failures are ignored.
  const ASK_MODEL_KEY = 'dsh.reading.askModel'
  function readStoredAskModel() {
    try {
      const raw = typeof localStorage !== 'undefined' ? localStorage.getItem(ASK_MODEL_KEY) : null
      if (!raw) return null
      const parsed = JSON.parse(raw)
      if (parsed && typeof parsed.provider === 'string' && typeof parsed.model === 'string') {
        return {
          provider: parsed.provider,
          model: parsed.model,
          ...(typeof parsed.reasoningEffort === 'string' && parsed.reasoningEffort
            ? { reasoningEffort: parsed.reasoningEffort }
            : {}),
        }
      }
    } catch {
      // Ignore a corrupt or unavailable slot.
    }
    return null
  }
  function writeStoredAskModel(selection) {
    try {
      if (typeof localStorage === 'undefined') return
      if (selection && selection.provider && selection.model) localStorage.setItem(ASK_MODEL_KEY, JSON.stringify(selection))
      else localStorage.removeItem(ASK_MODEL_KEY)
    } catch {
      // Storage may be unavailable; the in-memory choice still applies.
    }
  }
  const storedAskModel = readStoredAskModel()
  if (storedAskModel) {
    store.set((state) => ({ ...state, ask: { ...state.ask, selection: storedAskModel } }))
  }

  const toast = (message, tone = 'info') => set((state) => ({ ...state, toast: { message, tone, at: Date.now() } }))
  const dismissToast = () => set((state) => (state.toast ? { ...state, toast: null } : state))
  const fail = (error) => {
    const message = error instanceof Error ? error.message : String(error)
    if (error && error.name === 'AbortError') return
    toast(message, 'error')
  }

  const saveProgressDebounced = debounce((snapshot) => {
    const current = get().current
    if (!current) return
    api.rpc('book/progress', { id: current.book.id, ...snapshot }).catch(() => undefined)
  }, 1200)

  function computePercent(chapterIndex, scrollRatio, chapterCount) {
    const count = Math.max(1, chapterCount || 1)
    const raw = (chapterIndex + clamp(scrollRatio, 0, 1)) / count
    return clamp(raw, 0, 1)
  }

  async function bootstrap() {
    if (bootstrapped) return
    bootstrapped = true
    set((state) => ({ ...state, status: 'loading', error: null }))
    try {
      const shelf = await api.rpc('shelf', {})
      set((state) => ({ ...state, status: 'ready', shelf, error: null }))
    } catch (error) {
      bootstrapped = false
      set((state) => ({
        ...state,
        status: 'error',
        error: error instanceof Error ? error.message : String(error),
      }))
    }
  }

  async function refreshShelf() {
    try {
      const shelf = await api.rpc('shelf', {})
      set((state) => ({ ...state, shelf, status: 'ready' }))
      return shelf
    } catch (error) {
      fail(error)
      return null
    }
  }

  async function importFile(file) {
    if (!file) return null
    pendingImportAbort?.abort()
    const controller = new AbortController()
    pendingImportAbort = controller
    set((state) => ({ ...state, importing: true }))
    try {
      const result = await api.uploadEpub(file, controller.signal)
      set((state) => ({
        ...state,
        importing: false,
        shelf: {
          ...state.shelf,
          books: [result.book, ...state.shelf.books.filter((book) => book.id !== result.book.id)],
        },
      }))
      toast(tr(`已导入《${result.book.title}》，共 ${result.book.chapterCount} 章。`, `Imported "${result.book.title}" (${result.book.chapterCount} chapters).`))
      void refreshShelf()
      return result.book
    } catch (error) {
      if (!(error && error.name === 'AbortError')) set((state) => ({ ...state, importing: false }))
      fail(error)
      return null
    } finally {
      if (pendingImportAbort === controller) pendingImportAbort = null
    }
  }

  async function openBook(id) {
    if (!id) return
    set((state) => ({
      ...state,
      loadingBook: true,
      selection: null,
      view: 'reader',
      // A new book starts a fresh reader conversation; notes/bookmarks live in the library.
      ask: { ...state.ask, messages: [], draftQuote: null, streaming: false },
      reading: { ...state.reading, settingsOpen: false, notesOpen: false },
    }))
    try {
      const opened = await api.rpc('book/open', { id })
      set((state) => ({
        ...state,
        loadingBook: true,
        current: {
          book: opened.book,
          toc: opened.toc,
          chapterIndex: opened.chapterIndex,
          chapter: null,
          bookmarks: [],
        },
        notes: opened.notes || state.notes,
        loadingBook: true,
      }))
      const chapterIndex = opened.chapterIndex
      const [chapterData] = await Promise.all([
        api.rpc('book/chapter', { id, chapterIndex }),
        api.rpc('book/open-mark', { id, chapterIndex }).catch(() => undefined),
      ])
      const percent = computePercent(chapterIndex, opened.book.progress?.scrollRatio || 0, opened.toc.length)
      const scrollRatio = clamp(Number(opened.book.progress?.scrollRatio) || 0, 0, 1)
      set((state) => ({
        ...state,
        loadingBook: false,
        current: state.current
          ? { ...state.current, chapter: chapterData.chapter, chapterIndex, bookmarks: chapterData.bookmarks || [] }
          : state.current,
        progress: { chapterIndex, scrollRatio, percent },
      }))
      return chapterIndex
    } catch (error) {
      set((state) => ({ ...state, loadingBook: false, view: 'shelf' }))
      fail(error)
      return null
    }
  }

  async function loadChapter(chapterIndex, options = {}) {
    const current = get().current
    if (!current) return
    const index = clamp(Math.trunc(Number(chapterIndex) || 0), 0, Math.max(0, current.toc.length - 1))
    set((state) => ({ ...state, loadingBook: true, selection: null }))
    try {
      const data = await api.rpc('book/chapter', { id: current.book.id, chapterIndex: index })
      const scrollRatio = options.keepScroll ? 0 : 0
      const percent = computePercent(index, scrollRatio, current.toc.length)
      set((state) => ({
        ...state,
        loadingBook: false,
        current: state.current
          ? { ...state.current, chapterIndex: index, chapter: data.chapter, bookmarks: data.bookmarks || [] }
          : state.current,
        progress: { chapterIndex: index, scrollRatio, percent },
      }))
      saveProgressDebounced.flush({ chapterIndex: index, scrollRatio, percent })
    } catch (error) {
      set((state) => ({ ...state, loadingBook: false }))
      fail(error)
    }
  }

  function reportScroll(scrollRatio) {
    const state = get()
    const current = state.current
    if (!current) return
    const ratio = clamp(Number(scrollRatio) || 0, 0, 1)
    const percent = computePercent(current.chapterIndex, ratio, current.toc.length)
    const previous = state.progress
    if (Math.abs(previous.scrollRatio - ratio) < 0.0005 && Math.abs(previous.percent - percent) < 0.0005) return
    set({ ...state, progress: { chapterIndex: current.chapterIndex, scrollRatio: ratio, percent } })
    saveProgressDebounced({ chapterIndex: current.chapterIndex, scrollRatio: ratio, percent })
  }

  function flushProgress() {
    const state = get()
    if (!state.current) return
    saveProgressDebounced.flush({ ...state.progress })
  }

  function closeBook() {
    flushProgress()
    set((state) => ({ ...state, view: 'shelf', current: null, selection: null, search: { ...state.search, open: false } }))
    void refreshShelf()
  }

  function setView(view) {
    set((state) => ({ ...state, view }))
    if (view === 'notes') void loadNotes()
    if (view === 'shelf') void refreshShelf()
  }

  function setReadingPanel(patch) {
    set((state) => ({ ...state, reading: { ...state.reading, ...patch } }))
  }

  function setSelection(selection) {
    set((state) => ({ ...state, selection }))
  }

  function clearSelection() {
    set((state) => (state.selection ? { ...state, selection: null } : state))
  }

  async function setSettings(patch) {
    const previous = get().shelf.settings
    const next = { ...previous, ...patch }
    set((state) => ({ ...state, shelf: { ...state.shelf, settings: next } }))
    try {
      const result = await api.rpc('settings/save', { settings: patch })
      set((state) => ({ ...state, shelf: { ...state.shelf, settings: result.settings } }))
    } catch (error) {
      set((state) => ({ ...state, shelf: { ...state.shelf, settings: previous } }))
      fail(error)
    }
  }

  async function toggleBookmark() {
    const state = get()
    const current = state.current
    if (!current) return
    const existing = (current.bookmarks || []).find(
      (bookmark) => bookmark.chapterIndex === current.chapterIndex && Math.abs(bookmark.scrollRatio - state.progress.scrollRatio) < 0.02,
    )
    try {
      const result = existing
        ? await api.rpc('book/bookmark/remove', { id: current.book.id, bookmarkId: existing.id })
        : await api.rpc('book/bookmark/add', {
            id: current.book.id,
            chapterIndex: current.chapterIndex,
            scrollRatio: state.progress.scrollRatio,
            chapterTitle: current.chapter?.title || '',
            quote: state.selection?.text || '',
          })
      set((state) => ({
        ...state,
        current: state.current ? { ...state.current, bookmarks: result.bookmarks || [] } : state.current,
        reading: { ...state.reading, tocOpen: true },
      }))
      toast(existing ? tr('已移除书签', 'Bookmark removed') : tr('已添加书签', 'Bookmark added'))
    } catch (error) {
      fail(error)
    }
  }

  async function removeBookmark(bookmarkId) {
    const current = get().current
    if (!current) return
    try {
      const result = await api.rpc('book/bookmark/remove', { id: current.book.id, bookmarkId })
      set((state) => ({
        ...state,
        current: state.current ? { ...state.current, bookmarks: result.bookmarks || [] } : state.current,
      }))
    } catch (error) {
      fail(error)
    }
  }

  /** Stable id for one chat message. */
  function makeAskMessageId() {
    return `m_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`
  }

  /** Collect complete question/answer pairs for the model's short-term history. */
  function askHistory(messages) {
    const pairs = []
    let pending = null
    for (const message of messages) {
      if (!message || typeof message !== 'object') continue
      if (message.role === 'user') {
        pending = message
        continue
      }
      if (message.role === 'assistant' && pending && message.text) {
        pairs.push({ question: pending.text, answer: message.text })
        pending = null
      }
    }
    return pairs.slice(-4)
  }

  /**
   * Append one assistant message and stream the model answer into it.
   * The caller appends the user message first (see `askWithQuote`).
   */
  async function streamAnswer(question, quote, chapterIndex) {
    const current = get().current
    if (!current) return
    askAbort?.abort()
    const controller = new AbortController()
    askAbort = controller
    const assistantId = makeAskMessageId()
    const assistantMessage = {
      id: assistantId,
      role: 'assistant',
      text: '',
      reasoning: '',
      model: null,
      streaming: true,
      error: null,
      quote: '',
      question,
      chapterIndex,
      createdAt: Date.now(),
    }
    set((state) => ({
      ...state,
      ask: { ...state.ask, streaming: true, messages: [...state.ask.messages, assistantMessage] },
    }))
    const history = askHistory(get().ask.messages.slice(0, -1))
    const selection = get().ask.selection
    const patchAssistant = (patch) =>
      set((state) => ({
        ...state,
        ask: {
          ...state.ask,
          messages: state.ask.messages.map((message) =>
            message.id === assistantId ? { ...message, ...patch } : message,
          ),
        },
      }))
    try {
      await api.streamAsk(
        {
          id: current.book.id,
          chapterIndex,
          quote,
          question,
          history,
          ...(selection && selection.provider ? { provider: selection.provider } : {}),
          ...(selection && selection.model ? { model: selection.model } : {}),
          ...(selection && selection.reasoningEffort ? { reasoningEffort: selection.reasoningEffort } : {}),
        },
        {
          signal: controller.signal,
          onDelta: (delta) => patchAssistant({ text: (get().ask.messages.find((m) => m.id === assistantId)?.text || '') + delta }),
          onReasoning: (delta) =>
            patchAssistant({ reasoning: (get().ask.messages.find((m) => m.id === assistantId)?.reasoning || '') + delta }),
          onModel: (model) =>
            set((state) => ({
              ...state,
              ask: {
                ...state.ask,
                activeModel: model && model.model ? { provider: model.provider, model: model.model } : state.ask.activeModel,
                messages: state.ask.messages.map((message) =>
                  message.id === assistantId
                    ? { ...message, model: model && model.model ? { provider: model.provider, model: model.model } : message.model }
                    : message,
                ),
              },
            })),
          onError: (error) => patchAssistant({ streaming: false, error: error.message }),
          onDone: () =>
            set((state) => ({
              ...state,
              ask: {
                ...state.ask,
                streaming: false,
                messages: state.ask.messages.map((message) =>
                  message.id === assistantId ? { ...message, streaming: false } : message,
                ),
              },
            })),
        },
      )
    } catch (error) {
      if (error && error.name === 'AbortError') return
      patchAssistant({ streaming: false, error: error.message })
    } finally {
      if (askAbort === controller) askAbort = null
    }
  }

  /** Ask about a passage: append the user turn, then stream the answer. */
  async function askWithQuote(question, options = {}) {
    const state = get()
    const current = state.current
    if (!current) return null
    const trimmed = String(question || '').trim()
    if (!trimmed) return null
    const draft = state.ask.draftQuote || null
    const quote = typeof options.quote === 'string' ? options.quote : draft ? draft.text : ''
    const chapterIndex = Number.isInteger(options.chapterIndex)
      ? options.chapterIndex
      : draft && Number.isInteger(draft.chapterIndex)
        ? draft.chapterIndex
        : current.chapterIndex
    const userMessage = {
      id: makeAskMessageId(),
      role: 'user',
      text: trimmed,
      quote,
      chapterIndex,
      createdAt: Date.now(),
    }
    set((state) => ({
      ...state,
      selection: null,
      ask: { ...state.ask, draftQuote: null, messages: [...state.ask.messages, userMessage] },
    }))
    await streamAnswer(trimmed, quote, chapterIndex)
    return userMessage
  }

  /** Park a selection for the composer's next question ("自己提问"). */
  function beginQuestion(quote, chapterIndex) {
    const state = get()
    if (!state.current) return
    const text = String(quote || '').trim()
    set((state) => ({
      ...state,
      selection: null,
      ask: {
        ...state.ask,
        draftQuote: text
          ? {
              text,
              chapterIndex: Number.isInteger(chapterIndex) ? chapterIndex : state.current ? state.current.chapterIndex : 0,
            }
          : null,
      },
    }))
  }

  /** Drop the parked quote without asking. */
  function clearDraftQuote() {
    set((state) => (state.ask.draftQuote ? { ...state, ask: { ...state.ask, draftQuote: null } } : state))
  }

  function cancelAsk() {
    askAbort?.abort()
    askAbort = null
    set((state) => ({
      ...state,
      ask: {
        ...state.ask,
        streaming: false,
        messages: state.ask.messages.map((message) => (message.streaming ? { ...message, streaming: false } : message)),
      },
    }))
  }

  function clearChat() {
    askAbort?.abort()
    askAbort = null
    set((state) => ({ ...state, ask: { ...state.ask, messages: [], draftQuote: null, streaming: false } }))
  }

  /** Load the routable chat models for the composer's model picker. */
  async function loadAskModels() {
    const state = get()
    if (state.ask.models || state.ask.modelsLoading) return state.ask.models
    set((state) => ({ ...state, ask: { ...state.ask, modelsLoading: true, modelsError: null } }))
    try {
      const result = await api.rpc('ask/models', {})
      const models = result && result.models ? result.models : null
      // Never drop the user's chosen model just because a provider's model list was
      // slow, partial, or failed: the choice is what the next request sends.
      set((state) => ({
        ...state,
        ask: {
          ...state.ask,
          models,
          modelsLoading: false,
          modelsError: null,
        },
      }))
      return models
    } catch (error) {
      set((state) => ({ ...state, ask: { ...state.ask, modelsLoading: false, modelsError: error.message } }))
      return null
    }
  }

  /** Choose the route for future answers; `null` follows the default model. */
  function setAskModel(selection) {
    const value =
      selection && typeof selection.provider === 'string' && typeof selection.model === 'string'
        ? {
            provider: selection.provider,
            model: selection.model,
            ...(typeof selection.reasoningEffort === 'string' && selection.reasoningEffort
              ? { reasoningEffort: selection.reasoningEffort }
              : {}),
          }
        : null
    writeStoredAskModel(value)
    set((state) => ({ ...state, ask: { ...state.ask, selection: value } }))
  }

  /** Re-run the answer for one failed or cancelled assistant message. */
  async function retryAsk(messageId) {
    const state = get()
    const index = state.ask.messages.findIndex((message) => message.id === messageId)
    if (index < 0) return
    const assistant = state.ask.messages[index]
    if (!assistant || assistant.role !== 'assistant') return
    const user = [...state.ask.messages.slice(0, index)].reverse().find((message) => message.role === 'user')
    if (!user) return
    set((state) => ({
      ...state,
      ask: { ...state.ask, messages: state.ask.messages.filter((message) => message.id !== messageId) },
    }))
    await streamAnswer(user.text, user.quote, user.chapterIndex)
  }

  /** The user/assistant pair that one assistant message belongs to. */
  function findAskPair(messageId) {
    const messages = get().ask.messages
    const index = messages.findIndex((message) => message.id === messageId)
    if (index < 0) return null
    const assistant = messages[index]
    if (!assistant || assistant.role !== 'assistant') return null
    const user = [...messages.slice(0, index)].reverse().find((message) => message.role === 'user') || null
    return { user, assistant }
  }

  /** Persist one chat answer as a reading note. */
  async function saveMessageNote(messageId) {
    const state = get()
    const current = state.current
    const pair = findAskPair(messageId)
    if (!current || !pair || !pair.assistant.text) return null
    const chapterIndex = Number.isInteger(pair.assistant.chapterIndex)
      ? pair.assistant.chapterIndex
      : current.chapterIndex
    try {
      const result = await api.rpc('note/save', {
        note: {
          bookId: current.book.id,
          bookTitle: current.book.title,
          chapterIndex,
          chapterTitle: current.toc[chapterIndex]?.title || current.chapter?.title || '',
          quote: pair.user ? pair.user.quote : '',
          question: pair.user ? pair.user.text : '',
          answer: pair.assistant.text,
          note: '',
          tags: [],
        },
      })
      set((state) => ({
        ...state,
        notes: result.notes || state.notes,
        shelf: { ...state.shelf, notesCount: (result.notes || []).length },
      }))
      toast(tr('已存为笔记', 'Saved to notes'))
      return result.note
    } catch (error) {
      fail(error)
      return null
    }
  }

  /** Continue one chat answer in a normal conversation via the native composer. */
  async function bringMessageToConversation(messageId) {
    const state = get()
    const current = state.current
    const pair = findAskPair(messageId)
    if (!current || !pair) return
    const chapterIndex = Number.isInteger(pair.assistant.chapterIndex)
      ? pair.assistant.chapterIndex
      : current.chapterIndex
    try {
      const { prompt } = await api.rpc('conversation/prompt', {
        id: current.book.id,
        chapterIndex,
        quote: pair.user ? pair.user.quote : '',
        question: pair.user ? pair.user.text : '',
      })
      const uiWorkspace = ctx.get('uiWorkspace')
      if (!uiWorkspace || typeof uiWorkspace.startSession !== 'function') {
        throw readingError('reading/no-workspace', tr('当前页面无法创建对话。', 'This page cannot create a conversation.'))
      }
      uiWorkspace.startSession(undefined, { prompt, whenDraftExists: 'append' })
      toast(tr('已带入新对话，确认后发送即可。', 'Moved to a new conversation draft.'))
    } catch (error) {
      fail(error)
    }
  }

  async function loadNotes(query) {
    set((state) => ({ ...state, notesLoading: true, notesQuery: typeof query === 'string' ? query : state.notesQuery }))
    try {
      // Load the whole notebook: the notes page filters by book locally and the
      // reader-side drawer narrows to the open book, so scoping the read to the
      // current book would make "全部笔记" wrong.
      const notes = await api.rpc('note/list', {
        q: typeof query === 'string' ? query : get().notesQuery,
      })
      set((state) => ({ ...state, notes: notes.notes || [], notesLoading: false, shelf: { ...state.shelf, notesCount: (notes.notes || []).length } }))
    } catch (error) {
      set((state) => ({ ...state, notesLoading: false }))
      fail(error)
    }
  }

  async function saveNote(note) {
    try {
      const result = await api.rpc('note/save', { note })
      set((state) => ({ ...state, notes: result.notes || state.notes }))
      toast(tr('笔记已保存', 'Note saved'))
      return result.note
    } catch (error) {
      fail(error)
      return null
    }
  }

  async function deleteNote(id) {
    try {
      const result = await api.rpc('note/delete', { id })
      set((state) => ({ ...state, notes: result.notes || [] }))
      toast(tr('笔记已删除', 'Note deleted'))
    } catch (error) {
      fail(error)
    }
  }

  async function exportNotes(bookId) {
    try {
      const result = await api.rpc('note/export', { bookId })
      if (!result.count) {
        toast(tr('还没有笔记可以导出', 'No notes to export'))
        return
      }
      const stamp = new Date().toISOString().slice(0, 10)
      downloadText(`reading-notes-${stamp}.md`, result.markdown)
      toast(tr(`已导出 ${result.count} 条笔记`, `Exported ${result.count} notes`))
    } catch (error) {
      fail(error)
    }
  }

  async function search(query) {
    const q = String(query || '').trim()
    if (!q) {
      set((state) => ({ ...state, search: { ...state.search, results: [], q: '' } }))
      return
    }
    set((state) => ({ ...state, search: { ...state.search, q, loading: true } }))
    try {
      const { results } = await api.rpc('search', {
        q,
        bookId: get().current?.book.id,
        limit: 30,
      })
      set((state) => ({ ...state, search: { ...state.search, loading: false, results } }))
    } catch (error) {
      set((state) => ({ ...state, search: { ...state.search, loading: false } }))
      fail(error)
    }
  }

  function openSearch() {
    set((state) => ({ ...state, search: { ...state.search, open: true } }))
  }

  function closeSearch() {
    set((state) => ({ ...state, search: { ...state.search, open: false, results: [], q: '' } }))
  }

  const actions = {
    bootstrap,
    refreshShelf,
    importFile,
    openBook,
    loadChapter,
    reportScroll,
    flushProgress,
    closeBook,
    setView,
    setReadingPanel,
    setSelection,
    clearSelection,
    setSettings,
    toggleBookmark,
    removeBookmark,
    askWithQuote,
    beginQuestion,
    clearDraftQuote,
    cancelAsk,
    clearChat,
    loadAskModels,
    setAskModel,
    retryAsk,
    saveMessageNote,
    bringMessageToConversation,
    loadNotes,
    saveNote,
    deleteNote,
    exportNotes,
    search,
    openSearch,
    closeSearch,
    toast,
    dismissToast,
    fail,
  }

  READING_STORE = store
  READING_ACTIONS = actions
  READING_API = api
  return { store, actions, api }
}

// ---- client-src/40-shelf.js ----
/**
 * 40-shelf.js — the bookshelf view.
 *
 * Rendered inside `.rd-body` (owned by 80-panel). Fills the row, keeps the toolbar
 * fixed and scrolls the card grid itself. Sorting is purely client-side; the
 * selected mode only lives in component state.
 *
 * Delete is the one place where a view calls `api.rpc` directly: the store has no
 * `deleteBook` action, and this RPC is followed by `actions.refreshShelf()` plus a
 * toast, so the store ends up consistent. Everything else goes through `actions`.
 */

/** Cover tints for books without a usable cover image (percent of brand mixed in). */
const RD_SHELF_TINT_MIN = 8
const RD_SHELF_TINT_RANGE = 27

/** Density presets: grid column minimum width in px. */
const RD_SHELF_DENSITY = { standard: '160px', wide: '200px' }

/** Human "last read" label for a card's meta line. */
function shelfRelativeTime(value) {
  const timestamp = Number(value)
  if (!Number.isFinite(timestamp) || timestamp <= 0) return tr('尚未阅读', 'Not started')
  const diff = Math.max(0, Date.now() - timestamp)
  const minutes = Math.floor(diff / 60000)
  if (minutes < 1) return tr('刚刚', 'Just now')
  if (minutes < 60) return tr(`${minutes} 分钟前`, `${minutes} min ago`)
  const hours = Math.floor(diff / 3600000)
  if (hours < 24) return tr(`${hours} 小时前`, `${hours} h ago`)
  const days = Math.floor(diff / 86400000)
  if (days < 7) return tr(`${days} 天前`, `${days} d ago`)
  return formatDate(timestamp)
}

/** Deterministic tint percentage from a book id, so covers stay stable across renders. */
function shelfCoverTint(id) {
  const text = String(id || '')
  let hash = 0
  for (let index = 0; index < text.length; index += 1) hash = (hash * 31 + text.charCodeAt(index)) >>> 0
  return RD_SHELF_TINT_MIN + (hash % RD_SHELF_TINT_RANGE)
}

/** Cover image with a typographic fallback; falls back on load errors too. */
function ShelfCover({ book, api }) {
  const [failed, setFailed] = useState(false)
  const title = (book && book.title) || tr('未命名书籍', 'Untitled')
  const author = (book && typeof book.author === 'string' && book.author.trim()) || ''
  const source =
    !failed && book && book.cover && api && typeof api.coverUrl === 'function' ? api.coverUrl(book.id) : ''
  if (source) {
    return h(
      'div',
      { className: 'rd-shelf-cover' },
      h('img', {
        className: 'rd-shelf-cover-img',
        src: source,
        alt: title,
        loading: 'lazy',
        decoding: 'async',
        onError: () => setFailed(true),
      }),
    )
  }
  const tint = shelfCoverTint(book && book.id)
  return h(
    'div',
    {
      className: 'rd-shelf-cover rd-shelf-cover-fallback',
      'aria-hidden': true,
      style: {
        background: `linear-gradient(150deg, color-mix(in oklab, var(--dsw-alias-brand-primary) ${tint}%, var(--dsw-alias-bg-layer-2)), var(--dsw-alias-bg-layer-2))`,
      },
    },
    h('span', { className: 'rd-shelf-cover-title' }, title),
    author ? h('span', { className: 'rd-shelf-cover-author' }, author) : null,
  )
}

/** One shelf card: cover, metadata, progress, and hover/focus actions. */
function ShelfBookCard({ book, actions, api, onRequestDelete }) {
  const title = (book && book.title) || tr('未命名书籍', 'Untitled')
  const author = (book && typeof book.author === 'string' && book.author.trim()) || ''
  const chapterCount = Math.max(0, Math.trunc(Number(book && book.chapterCount) || 0))
  const progress = book && book.progress && typeof book.progress === 'object' ? book.progress : {}
  const percent = clamp(Number(progress.percent) || 0, 0, 1)
  const started = percent > 0 || Number(book && book.openedCount) > 0
  const chapterLabel =
    chapterCount > 0
      ? chapterCount === 1
        ? tr('1 章', '1 chapter')
        : tr(`${chapterCount} 章`, `${chapterCount} chapters`)
      : tr('暂无章节', 'No chapters')
  return h(
    'article',
    { className: 'rd-shelf-card' },
    h(ShelfCover, { book, api }),
    h(
      'div',
      { className: 'rd-shelf-card-body' },
      h('div', { className: 'rd-shelf-card-title', title }, title),
      h('div', { className: 'rd-shelf-card-author' }, author || tr('未知作者', 'Unknown author')),
      h(
        'div',
        { className: 'rd-shelf-card-meta' },
        h('span', null, chapterLabel),
        h('span', null, shelfRelativeTime(book && book.lastReadAt)),
      ),
      h(
        'div',
        { className: 'rd-shelf-card-progress' },
        h(Progress, { value: percent }),
        h('span', { className: 'rd-shelf-percent' }, `${Math.round(percent * 100)}%`),
      ),
    ),
    h('button', {
      type: 'button',
      className: 'rd-shelf-card-open',
      onClick: () => void actions.openBook(book.id),
      title: tr(`打开《${title}》`, `Open "${title}"`),
      'aria-label': tr(`打开《${title}》`, `Open "${title}"`),
    }),
    h(
      'div',
      { className: 'rd-shelf-card-actions' },
      h(
        Button,
        {
          variant: 'primary',
          size: 'sm',
          icon: 'bookOpen',
          title: started ? tr('继续阅读', 'Continue reading') : tr('开始阅读', 'Start reading'),
          onClick: () => void actions.openBook(book.id),
        },
        started ? tr('继续阅读', 'Continue') : tr('开始阅读', 'Start'),
      ),
      h(IconButton, {
        icon: 'trash',
        label: tr(`删除《${title}》`, `Delete "${title}"`),
        className: 'rd-shelf-delete',
        onClick: () => onRequestDelete(book),
      }),
    ),
  )
}

/** Empty shelf: import guidance, window drag hint and the library location. */
function ShelfEmptyState({ actions, libraryDir }) {
  const inputRef = useRef(null)
  const onFiles = (event) => {
    const input = event && event.target
    const file = input && input.files && input.files[0]
    if (input) input.value = ''
    if (!file) return
    if (!/\.epub$/i.test(String(file.name || ''))) {
      actions.toast(tr('目前只支持 EPUB 文件。', 'Only EPUB files are supported for now.'), 'error')
      return
    }
    void actions.importFile(file)
  }
  return h(
    'div',
    { className: 'rd-shelf-empty' },
    h(Empty, {
      icon: 'bookOpen',
      title: tr('书架还是空的', 'Your shelf is empty'),
      description: tr(
        '把 EPUB 文件拖到窗口任意位置即可导入；也可以点下面的按钮，或使用右上角的「导入 EPUB」。书库保存在 Host 上，换浏览器也不会丢。',
        'Drag an EPUB anywhere onto the window to import, or use the button below (or “Import EPUB” in the header). Books live on the Host, so they survive browser changes.',
      ),
      action: h(
        Button,
        {
          variant: 'primary',
          icon: 'upload',
          title: tr('导入 EPUB 文件', 'Import an EPUB file'),
          onClick: () => inputRef.current?.click(),
        },
        tr('导入 EPUB', 'Import EPUB'),
      ),
    }),
    libraryDir
      ? h(
          'div',
          { className: 'rd-shelf-library', title: libraryDir },
          tr(`书库位置：${libraryDir}`, `Library: ${libraryDir}`),
        )
      : null,
    h('input', {
      ref: inputRef,
      type: 'file',
      accept: '.epub,application/epub+zip',
      style: { display: 'none' },
      onChange: onFiles,
    }),
  )
}

/** The bookshelf page body. */
function ShelfView({ state, actions, api }) {
  const shelf = state.shelf && typeof state.shelf === 'object' ? state.shelf : {}
  const books = Array.isArray(shelf.books) ? shelf.books : []
  const libraryDir = typeof shelf.libraryDir === 'string' ? shelf.libraryDir : ''
  const [sort, setSort] = useState('recent')
  const [density, setDensity] = useState('standard')
  const [pendingDelete, setPendingDelete] = useState(null)
  const [deleting, setDeleting] = useState(false)

  const sortedBooks = useMemo(() => {
    const list = books.slice()
    if (sort === 'title') {
      list.sort((left, right) => String(left.title || '').localeCompare(String(right.title || ''), 'zh-Hans-CN'))
      return list
    }
    if (sort === 'added') {
      list.sort((left, right) => (Number(right.addedAt) || 0) - (Number(left.addedAt) || 0))
      return list
    }
    list.sort((left, right) => {
      const leftRead = Number(left.lastReadAt) || 0
      const rightRead = Number(right.lastReadAt) || 0
      if (leftRead !== rightRead) return rightRead - leftRead
      return (Number(right.addedAt) || 0) - (Number(left.addedAt) || 0)
    })
    return list
  }, [books, sort])

  const closeDelete = useCallback(() => {
    if (deleting) return
    setPendingDelete(null)
  }, [deleting])

  /** Delete one book through the Host RPC, then refresh the shelf snapshot. */
  const confirmDelete = useCallback(async () => {
    const book = pendingDelete
    if (!book || !book.id || deleting) return
    setDeleting(true)
    try {
      await api.rpc('book/delete', { id: book.id })
      setPendingDelete(null)
      actions.toast(tr(`已删除《${book.title || '未命名书籍'}》`, `Deleted "${book.title || 'Untitled'}"`))
      await actions.refreshShelf()
    } catch (error) {
      actions.fail(error)
    } finally {
      setDeleting(false)
    }
  }, [actions, api, deleting, pendingDelete])

  const sortOptions = [
    { value: 'recent', label: tr('最近阅读', 'Recent') },
    { value: 'added', label: tr('导入时间', 'Added') },
    { value: 'title', label: tr('书名', 'Title') },
  ]

  return h(
    'div',
    { className: 'rd-shelf' },
    books.length > 0
      ? h(
          'div',
          { className: 'rd-shelf-toolbar' },
          h('span', { className: 'rd-shelf-count' }, tr(`${books.length} 本`, `${books.length} ${books.length === 1 ? 'book' : 'books'}`)),
          h('span', { className: 'rd-shelf-toolbar-spacer' }),
          h(
            Button,
            {
              variant: 'secondary',
              size: 'sm',
              icon: 'search',
              title: tr('搜索所有书籍正文', 'Search inside all books'),
              onClick: () => actions.openSearch(),
            },
            tr('搜索正文', 'Search text'),
          ),
          h(Segmented, { value: sort, options: sortOptions, onChange: setSort, label: tr('排序方式', 'Sort by') }),
          h(
            Button,
            {
              variant: 'ghost',
              size: 'sm',
              title: tr('切换卡片密度', 'Toggle card density'),
              onClick: () => setDensity((current) => (current === 'wide' ? 'standard' : 'wide')),
            },
            density === 'wide' ? tr('宽松', 'Wide') : tr('标准', 'Standard'),
          ),
        )
      : null,
    state.importing
      ? h(
          'div',
          { className: 'rd-shelf-importing', role: 'status' },
          h(Spinner, { size: 14 }),
          tr('正在导入 EPUB，请稍候…', 'Importing EPUB…'),
        )
      : null,
    books.length === 0
      ? h(ShelfEmptyState, { actions, libraryDir })
      : h(
          'div',
          { className: 'rd-shelf-scroll' },
          h(
            'div',
            {
              className: 'rd-shelf-grid',
              style: { '--rd-shelf-min': RD_SHELF_DENSITY[density] || RD_SHELF_DENSITY.standard },
            },
            sortedBooks.map((book) =>
              h(ShelfBookCard, {
                key: book.id,
                book,
                actions,
                api,
                onRequestDelete: setPendingDelete,
              }),
            ),
          ),
        ),
    h(Dialog, {
      open: Boolean(pendingDelete),
      onClose: closeDelete,
      width: 440,
      title: tr('删除这本书？', 'Delete this book?'),
      description: pendingDelete
        ? tr(
            `《${pendingDelete.title}》的正文、封面和阅读进度会从书库中删除，相关的问答笔记也会一并删除。此操作无法撤销。`,
            `"${pendingDelete.title}" and its cover, reading progress and related Q&A notes will be removed from the library. This cannot be undone.`,
          )
        : '',
      footer: [
        h(
          Button,
          { key: 'cancel', variant: 'ghost', onClick: closeDelete, disabled: deleting },
          tr('取消', 'Cancel'),
        ),
        h(
          Button,
          { key: 'delete', variant: 'danger', icon: 'trash', onClick: () => void confirmDelete(), disabled: deleting },
          deleting ? tr('删除中…', 'Deleting…') : tr('删除', 'Delete'),
        ),
      ],
    }),
  )
}

